def compare_one(a, b):
    def parse_value(val):
        if isinstance(val, str):
            val = val.replace(',', '.')
            return float(val) if val.replace('.', '', 1).isdigit() else val
        return val

    a_parsed = parse_value(a)
    b_parsed = parse_value(b)

    if a_parsed == b_parsed:
        return None
    return a if a_parsed > b_parsed else b
